const embeddedPhotos={"hero":"data:image/jpeg;base64,","bmw-m3":"data:image/jpeg;base64,","dodge-charger":"data:image/jpeg;base64,","ford-mustang":"data:image/jpeg;base64,","toyota-supra":"data:image/jpeg;base64,","porsche-911":"data:image/jpeg;base64,","corvette":"data:image/jpeg;base64,","gtr":"data:image/jpeg;base64,","amg-gt":"data:image/jpeg;base64,","audi-rs6":"data:image/jpeg;base64,","lexus-lc500":"data:image/jpeg;base64,","honda-type-r":"data:image/jpeg;base64,","subaru-wrx":"data:image/jpeg;base64,","viewer-bmw":"data:image/jpeg;base64,"};
if(embeddedPhotos.hero)document.documentElement.style.setProperty('--hero-photo', `url(\"${embeddedPhotos.hero}\")`);
function carPhoto(c){return embeddedPhotos[c.id]||embeddedPhotos['bmw-m3']||''}
function attachImageFallbacks(root=document){root.querySelectorAll('img.car-photo,img[data-car-photo]').forEach(img=>{if(img.dataset.fallbackBound)return;img.dataset.fallbackBound='1';img.addEventListener('error',()=>{const fallback=embeddedPhotos['bmw-m3'];if(fallback&&img.src!==fallback){img.src=fallback}})})}
if(window.DF_HERO){document.documentElement.style.setProperty('--hero-photo', `url(\"${window.DF_HERO}\")`)}
const brands=['ALL',...new Set(cars.map(c=>c.brand))];
const state={car:'bmw-m3',brand:'ALL',search:'',tab:'vehicle',paint:'#3d4650',finish:'metallic',wheel:'stock',body:'stock',engine:'stock',drive:'awd',interior:'black',pro:false,ride:0,track:0,customHp:523};
const paints=[['#101214','Obsidian','Metallic',0],['#c7c9cc','Silver','Metallic',650],['#8f121c','Crimson','Pearl',950],['#173d6d','Deep Blue','Metallic',950],['#d4d3ce','Chalk','Gloss',350],['#28302d','Stealth Green','Satin',1250],['#4a4e54','Graphite','Matte',1600]];
const wheels=[['stock','20” Sport','Included',0],['mesh','21” Mesh','Gunmetal',1800],['forged','22” Forged','Brushed',4800],['carbon','22” Carbon','Carbon',6200]];
const bodies=[['stock','Stock','Factory form',0],['sport','Sport','Subtle aero',1800],['wide','Widebody','Fender flares',7200,true],['track','Track','Splitter + wing',8900,true],['luxury','Luxury','Comfort aero',6500,true]];
const engines=[['stock','Factory','Keep selected profile',0],['i6','I6 Turbo','+90 HP',6200],['v8','V8 Twin-Turbo','+167 HP',14500],['v10','V10 N/A','+257 HP',21000,true],['v12','V12 Twin-Turbo','+377 HP',32000,true],['ev','Dual Motor EV','+110 HP',12000]];
function $(s){return document.querySelector(s)}
function car(){return cars.find(c=>c.id===state.car)||cars[0]}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.remove('hidden');clearTimeout(window.toastT);window.toastT=setTimeout(()=>el.classList.add('hidden'),2200)}
function renderBrands(){const row=$('#brandRow');row.innerHTML=brands.map(b=>`<button class="brand ${state.brand===b?'active':''}" data-brand="${b}">${b}</button>`).join('')}
function filteredCars(){const q=state.search.toLowerCase();return cars.filter(c=>(state.brand==='ALL'||c.brand===state.brand)&&(!q||(c.brand+' '+c.name+' '+c.category).toLowerCase().includes(q)))}
function art(c){return `<div class="car-art"><img class="car-photo" loading="lazy" src="${carPhoto(c)}" alt="${c.brand} ${c.name}" onerror="this.onerror=null;this.src='${embeddedPhotos['bmw-m3']}'"><span class="car-photo-shade"></span></div>`}
function renderGarage(){const grid=$('#garageGrid');grid.innerHTML=filteredCars().map(c=>`<button type="button" class="car-card ${state.car===c.id?'selected':''}" data-car="${c.id}" aria-pressed="${state.car===c.id}">${art(c)}<div class="car-info"><span class="brand-name">${c.brand}</span><h3>${c.name}</h3><span class="meta">${c.year} · ${c.category}</span><div class="row"><span class="price">$${c.price.toLocaleString()}</span><span class="select-mark">${state.car===c.id?'SELECTED ✓':'SELECT MODEL →'}</span></div></div></button>`).join('')||'<div class="notice">No vehicles match that search.</div>'}
function showHome(){document.querySelector('#homeView').classList.remove('hidden');document.querySelector('#studioView').classList.add('hidden')}
function showStudio(){document.querySelector('#homeView').classList.add('hidden');document.querySelector('#studioView').classList.remove('hidden');renderPanel();renderScene()}
function optionHtml(arr,current,kind){return arr.map(o=>{const locked=o[4]&&!state.pro;return `<button class="option ${current===o[0]?'active':''}" data-kind="${kind}" data-id="${o[0]}" ${locked?'data-locked="1"':''}><strong>${o[1]}</strong><small>${o[2]} · ${o[3]?'$'+o[3].toLocaleString():'Included'}</small>${locked?'<span class="pro-pill">PRO</span>':''}</button>`}).join('')}
function renderPanel(){const c=car();let h='';if(state.tab==='vehicle'){h=`<div class="panel-section"><h4>Garage selection</h4><div class="notice">Select a vehicle. The preview, specifications, price and build state change immediately.</div><div class="vehicle-option-grid">${cars.map(x=>`<button type="button" class="vehicle-option ${state.car===x.id?'active':''}" data-kind="car" data-id="${x.id}" aria-pressed="${state.car===x.id}"><img loading="lazy" src="${carPhoto(x)}" alt="${x.brand} ${x.name}"><span><b>${x.brand}</b><strong>${x.name}</strong><small>${x.category} · $${x.price.toLocaleString()}</small></span>${state.car===x.id?'<em>✓</em>':''}</button>`).join('')}</div></div>`;}
if(state.tab==='paint'){h=`<div class="panel-section"><h4>Paint</h4><div class="swatches">${paints.map(p=>`<button class="swatch ${state.paint===p[0]?'active':''}" data-kind="paint" data-id="${p[0]}" style="background:${p[0]}" title="${p[1]}"></button>`).join('')}</div><div class="notice" style="margin-top:12px">${paints.find(p=>p[0]===state.paint)[1]} · ${paints.find(p=>p[0]===state.paint)[2]}</div></div><div class="panel-section"><h4>Finish</h4><div class="option-grid">${[['metallic','Metallic','Reflective clearcoat',0],['matte','Matte','Low-reflection surface',1600],['satin','Satin','Soft sheen',1250],['gloss','Gloss','High gloss',350]].map(o=>`<button class="option ${state.finish===o[0]?'active':''}" data-kind="finish" data-id="${o[0]}"><strong>${o[1]}</strong><small>${o[2]} · ${o[3]?'$'+o[3]:'Included'}</small></button>`).join('')}</div></div>`}
if(state.tab==='wheels'){h=`<div class="panel-section"><h4>Wheel design</h4><div class="option-grid">${optionHtml(wheels,state.wheel,'wheel')}</div></div><div class="panel-section"><h4>Stance</h4>${slider('ride','Ride height',state.ride,-25,15,' mm')}${slider('track','Track width',state.track,-8,22,' mm')}</div>`}
if(state.tab==='body'){h=`<div class="panel-section"><h4>Body program</h4><div class="option-grid">${optionHtml(bodies,state.body,'body')}</div></div><div class="panel-section"><h4>Aerodynamics</h4><div class="option-grid">${[['clean','Clean','Road-focused aero',0],['active','Active','Adaptive aero',4500],['race','Race','High-downforce aero',9800,true]].map(o=>`<button class="option ${state.aero===o[0]?'active':''}" data-kind="aero" data-id="${o[0]}" ${o[4]&&!state.pro?'data-locked="1"':''}><strong>${o[1]}</strong><small>${o[2]} · ${o[3]?'$'+o[3].toLocaleString():'Included'}</small>${o[4]&&!state.pro?'<span class="pro-pill">PRO</span>':''}</button>`).join('')}</div></div>`}
if(state.tab==='power'){const e=engines.find(x=>x[0]===state.engine);h=`<div class="panel-section"><h4>Engine</h4><div class="option-grid">${optionHtml(engines,state.engine,'engine')}</div></div><div class="panel-section"><h4>Drivetrain</h4><div class="option-grid">${[['fwd','FWD','Front drive',0],['rwd','RWD','Rear drive',1200],['awd','AWD','All wheel drive',3200]].map(o=>`<button class="option ${state.drive===o[0]?'active':''}" data-kind="drive" data-id="${o[0]}"><strong>${o[1]}</strong><small>${o[2]} · ${o[3]?'$'+o[3].toLocaleString():'Included'}</small></button>`).join('')}</div></div><div class="panel-section"><h4>Power tuning</h4>${slider('tune','Power target',0,0,120,' %')}</div>`}
if(state.tab==='interior'){h=`<div class="panel-section"><h4>Interior theme</h4><div class="option-grid">${[['black','Black Leather','Technical',0],['tan','Saddle Leather','Warm',1200],['red','Burgundy','Sport',1500],['alcantara','Alcantara + Leather','Track',2100],['carbon','Carbon + Alcantara','Premium',3900,true]].map(o=>`<button class="option ${state.interior===o[0]?'active':''}" data-kind="interior" data-id="${o[0]}" ${o[4]&&!state.pro?'data-locked="1"':''}><strong>${o[1]}</strong><small>${o[2]} · ${o[3]?'$'+o[3].toLocaleString():'Included'}</small>${o[4]&&!state.pro?'<span class="pro-pill">PRO</span>':''}</button>`).join('')}</div></div>`}
$('#panelBody').innerHTML=h;attachImageFallbacks($('#panelBody'))}
function slider(id,label,val,min,max,suffix){return `<div class="range-row"><span>${label}</span><b id="${id}Value">${val>0?'+':''}${val}${suffix}</b></div><input class="range" id="${id}Range" type="range" min="${min}" max="${max}" value="${val}">`}
function renderScene(){const c=car();const v=$('#viewerCar');v.className='viewer-car '+c.type+' '+state.body;v.style.setProperty('--photo',`url('${carPhoto(c)}')`);v.style.setProperty('--paint',state.paint);v.setAttribute('aria-label',c.brand+' '+c.name+' preview');$('#viewerName').textContent=c.brand+' '+c.name;$('#viewerMeta').textContent=c.year+' · '+c.category+' · '+state.drive.toUpperCase();$('#buildTitle').textContent=c.brand+' '+c.name;$('#buildSubtitle').textContent=c.tag+' · DriveForge visualization';updateStats()}
function updateStats(){const c=car();const eng=engines.find(e=>e[0]===state.engine)||engines[0];let hp=c.hp,zero=c.zero,top=c.top,price=c.price; if(state.engine!=='stock'){const delta=Number(eng[2].match(/\+([0-9]+)/)?.[1]||0);hp+=delta;zero=Math.max(2.2,zero-delta*.003);top=Math.min(380,top+delta*.035);price+=eng[3]}price+=paints.find(p=>p[0]===state.paint)?.[3]||0;price+=wheels.find(w=>w[0]===state.wheel)?.[3]||0;price+=bodies.find(b=>b[0]===state.body)?.[3]||0; if(state.ride<0)zero-=.05; if(state.track>0)zero-=.03;$('#statHp').textContent=Math.round(hp);$('#statZero').textContent=Math.max(2.2,zero).toFixed(1);$('#statTop').textContent=Math.round(top);$('#buildPrice').textContent='$'+Math.round(price).toLocaleString()}
$('#garageGrid').addEventListener('click',e=>{const card=e.target.closest('[data-car]');if(!card)return;e.preventDefault();state.car=card.dataset.car;const c=car();state.paint=c.color;state.engine='stock';state.body='stock';renderGarage();showStudio();renderPanel();renderScene();toast(c.brand+' '+c.name+' selected')});
$('#brandRow').addEventListener('click',e=>{const b=e.target.closest('[data-brand]');if(!b)return;state.brand=b.dataset.brand;renderBrands();renderGarage()});
$('#searchInput').addEventListener('input',e=>{state.search=e.target.value;renderGarage()});
$('#panelTabs').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(!b)return;state.tab=b.dataset.tab;document.querySelectorAll('#panelTabs button').forEach(x=>x.classList.toggle('active',x===b));renderPanel()});
$('#panelBody').addEventListener('click',e=>{const b=e.target.closest('.option,.swatch');if(!b)return;if(b.dataset.locked){$('#premiumModal').classList.remove('hidden');return}const k=b.dataset.kind,id=b.dataset.id;if(k==='car'){state.car=id;state.paint=car().color;state.engine='stock';state.body='stock';renderGarage();renderScene();renderPanel();toast(car().brand+' '+car().name+' selected')}else if(k==='paint'){state.paint=id;renderScene();renderPanel()}else if(k==='finish'){state.finish=id;renderPanel()}else if(k==='wheel'){state.wheel=id;renderScene();renderPanel()}else if(k==='body'){state.body=id;renderScene();renderPanel()}else if(k==='aero'){state.aero=id;renderPanel()}else if(k==='engine'){state.engine=id;renderScene();renderPanel()}else if(k==='drive'){state.drive=id;renderScene();renderPanel()}else if(k==='interior'){state.interior=id;renderPanel()}updateStats()});
$('#panelBody').addEventListener('input',e=>{if(e.target.matches('.range')){const id=e.target.id.replace('Range','');state[id]=Number(e.target.value);const out=document.querySelector('#'+id+'Value');if(out)out.textContent=(state[id]>0?'+':'')+state[id]+(id==='ride'||id==='track'?' mm':' %');const v=$('#viewerCar');if(id==='ride')v.style.bottom=(28-state.ride*.5)+'px'; if(id==='track')v.style.left='50%'; updateStats()}});
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-view]').forEach(x=>x.classList.remove('active'));b.classList.add('active');const view=b.dataset.view;$('#viewerCar').style.filter=view==='interior'?'brightness(.72) contrast(1.1)':'none';$('#viewerCar').style.transform=view==='rear'?'translate(-50%,-40%) scaleX(-1)':view==='side'?'translate(-50%,-42%) scaleX(1.03)':'translate(-50%,-42%)'}));
$('#saveBuildBtn').addEventListener('click',()=>{const c=car();const blob=new Blob([JSON.stringify({...state,vehicle:c.name},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='driveforge-build.json';a.click();URL.revokeObjectURL(a.href);toast('Build saved')});
$('#premiumBtn').addEventListener('click',()=>$('#premiumModal').classList.remove('hidden'));$('#closePremium').addEventListener('click',()=>$('#premiumModal').classList.add('hidden'));$('#unlockPremium').addEventListener('click',()=>{state.pro=true;$('#premiumModal').classList.add('hidden');$('#premiumBtn').textContent='♛ Pro Garage · UNLOCKED';renderPanel();toast('Pro Garage unlocked — demo only')});
function start(mode){$('#modeScreen').classList.add('hidden');if(mode==='scratch'){state.car='lamborghini-revuelto';state.paint='#9a5c09';state.body='wide';state.engine='v12';state.pro=true;state.tab='body'}else{state.car='bmw-m3';state.paint=car().color;state.engine='stock';state.body='stock';state.tab='vehicle'}showStudio()}
document.querySelectorAll('[data-start-mode]').forEach(b=>b.addEventListener('click',()=>start(b.dataset.startMode)));
$('#heroBuild').addEventListener('click',()=>$('#modeScreen').classList.remove('hidden'));$('#heroGarage').addEventListener('click',()=>document.querySelector('#garageSection').scrollIntoView({behavior:'smooth'}));document.querySelector('[data-garage]').addEventListener('click',()=>document.querySelector('#garageSection')?.scrollIntoView({behavior:'smooth'}));document.querySelector('[data-home]').addEventListener('click',showHome);document.querySelector('[data-build]').addEventListener('click',()=>$('#modeScreen').classList.remove('hidden'));document.querySelector('[data-catalog]').addEventListener('click',()=>document.querySelector('#garageSection').scrollIntoView({behavior:'smooth'}));$('#savedBtn').addEventListener('click',()=>toast('Saved builds are stored as JSON from the Build screen'));
renderBrands();renderGarage();attachImageFallbacks();
